        "allow_list": "What this token may call",
        "token_inherits": "A token inherits your permissions and then narrows them. It can never exceed what you can do, and delete, billing and member management are not in the registry at all.",
        "self_hosted_note": "Self-hosted means the MCP endpoint is on your network. Your code and your task data never leave it — only the model call does, and that can point at your own GPU.",
        "attrib_lead": "Person, tool, then account type — in that order, everywhere.",
        "attrib_title": "How it reads on the task",
